#!/usr/bin/env python3
"""Write include/tutk_shared.h from the C blocks of the TUTK kit's shared docs.

    gen_header.py KIT_DIR [OUT]

KIT_DIR is the kit root (the directory holding docs/shared/). The header is generated, not edited:
fix the kit and regenerate.
"""
import pathlib
import re
import sys

DOCS = ("docs/shared/10-errors.md", "docs/shared/20-types.md")

HEAD = """\
/* Generated by tools/gen_header.py from the TUTK kit's shared docs; do not edit. */
#ifndef TUTK_SHARED_H
#define TUTK_SHARED_H

#include <stdint.h>
#include <netinet/in.h>

"""

TAIL = "\n#endif\n"


def main(argv):
    kit = pathlib.Path(argv[1])
    out = pathlib.Path(argv[2]) if len(argv) > 2 else pathlib.Path(__file__).parent.parent / "include/tutk_shared.h"
    parts = [HEAD]
    for doc in DOCS:
        text = (kit / doc).read_text()
        parts.append(f"/* ---- {doc} ---- */\n\n")
        for block in re.findall(r"```c\n(.*?)```", text, re.S):
            parts.append(block.rstrip() + "\n\n")
    parts.append(TAIL)
    out.write_text("".join(parts))


if __name__ == "__main__":
    main(sys.argv)
